    r1.interfaces['Gig0/1'].ip = '10.0.12.1';
    r1.interfaces['Gig0/1'].subnetMask = '255.255.255.252';

    r2.interfaces['Gig0/0'].ip = '10.0.12.2';
    r2.interfaces['Gig0/0'].subnetMask = '255.255.255.252';
