    addConnection(pc1.id, sw2.id);
    addConnection(sw0.id, sw1.id);
    addConnection(sw0.id, sw2.id);
    addConnection(sw1.id, sw2.id); // Redundant link (Sw2 side will be blocked)

    recalculateTopologyStp();

