    executeCliCommand(r0, 'conf t');
    executeCliCommand(r0, 'interface Gig0/0');
    executeCliCommand(r0, 'ip address 192.168.1.1 255.255.255.0');
    executeCliCommand(r0, 'no shutdown');
    executeCliCommand(r0, 'exit');
