    executeCliCommand(r1, 'router ospf 1');
    executeCliCommand(r1, 'network 10.0.12.0 0.0.0.3 area 0');
    executeCliCommand(r1, 'network 192.168.2.0 0.0.0.255 area 0');

    simulateOspfHello(r0.id, r1.id);
