    r0.interfaces['Gig0/0'].subnetMask = '255.255.255.0';
    r0.interfaces['Gig0/1'].ip = '203.0.113.1';
    r0.interfaces['Gig0/1'].subnetMask = '255.255.255.0';

    pc1.ip = '203.0.113.100';
    pc1.subnetMask = '255.255.255.0';
    pc1.gateway = '203.0.113.1';

